import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';

export default function Signup() {
  const { setPage, register, dark } = useApp();
  const css = getTheme(dark);

  const [form, setForm]       = useState({ name: '', email: '', password: '', role: 'student', college: '' });
  const [loading, setLoading] = useState(false);
  const [errors, setErrors]   = useState({});

  const [colleges, setColleges] = useState([]);
  const [collegesLoading, setCollegesLoading] = useState(true);

  useEffect(() => {
    fetch('http://localhost:5000/api/colleges')
      .then((r) => r.json())
      .then((data) => { setColleges(data); setCollegesLoading(false); })
      .catch(() => setCollegesLoading(false));
  }, []);

  const validate = () => {
    const e = {};
    if (!form.name.trim())                          e.name     = 'Name is required';
    if (!form.email.trim())                         e.email    = 'Email is required';
    if (!form.password || form.password.length < 8) e.password = 'Minimum 8 characters';
    if (!/[A-Z]/.test(form.password))               e.password = 'Must include an uppercase letter';
    if (!/[0-9]/.test(form.password))               e.password = 'Must include a number';
    if (!/[!@#$%^&*]/.test(form.password))          e.password = 'Must include a special character';
    if (form.role === 'student' && !form.college)   e.college  = 'Please select your college';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handle = async () => {
    if (!validate()) return;
    setLoading(true);

    await new Promise((r) => setTimeout(r, 500));

    // ✅ FIXED: ensure college always sent properly
    await register({
      ...form,
      college: form.role === 'student' ? form.college : '',
    });

    setLoading(false);
  };

  const handleKey = (e) => { if (e.key === 'Enter') handle(); };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: 24,
      background: dark ? '#050810' : '#f8f9ff',
      position: 'relative', overflow: 'hidden',
    }}>

      <div style={{ width: '100%', maxWidth: 440 }}>

        <div style={{ textAlign: 'center', marginBottom: 36 }}>
          <h1 style={{ fontSize: 30, fontWeight: 800 }}>
            Create account
          </h1>
        </div>

        <div style={{ ...css.card, padding: 32 }}>

          <input
            placeholder="Full Name"
            value={form.name}
            onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
          />

          <input
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm((p) => ({ ...p, email: e.target.value }))}
          />

          <input
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={(e) => setForm((p) => ({ ...p, password: e.target.value }))}
          />

          <select
            value={form.role}
            onChange={(e) => setForm((p) => ({ ...p, role: e.target.value, college: '' }))}
          >
            <option value="student">Student</option>
            <option value="teacher">Teacher</option>
          </select>

          {form.role === 'student' && (
            <select
              value={form.college}
              onChange={(e) => setForm((p) => ({ ...p, college: e.target.value }))}
            >
              <option value="">
                {collegesLoading ? 'Loading...' : 'Select college'}
              </option>
              {colleges.map((c) => (
                <option key={c._id} value={c._id}>
                  {c.name}
                </option>
              ))}
            </select>
          )}

          <button onClick={handle} disabled={loading}>
            {loading ? 'Please wait...' : 'Create account'}
          </button>

        </div>

        <button onClick={() => setPage('login')}>
          Already have account? Login
        </button>

      </div>
    </div>
  );
}
